/**
 * Round 34 of the hook lane (sentence check 30): an option word is read only in an exact spelling
 * (B1), checked against the tools' own parsers (npm's nopt, pip's optparse, fixtures generated by
 * scripts/gen-npm-option-spellings.cjs and scripts/gen-pip-option-spellings.py); a requirements
 * file is read strictly (B2); Go's flag forms of `go env -w` (B3); `pip config --editor x edit`
 * (B4); the older-server denial text (B5); a spec of exclusions is a range.
 */

import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { afterAll, beforeAll, describe, expect, it } from "vitest";

import { respond } from "../../hooks/manifest-edit.mjs";
// The hook's PATH lookups see a stub for each manager and runner word, whatever the machine (Windows).
import "./helpers/a1125-manager-stubs.js";

const NPM = JSON.parse(readFileSync(join(__dirname, "fixtures", "a1125-npm-spellings.json"), "utf8")) as { npm: string; spellings: { opt: string; consumed: boolean }[] };
const PIP = JSON.parse(readFileSync(join(__dirname, "fixtures", "a1125-pip-spellings.json"), "utf8")) as { pip: string; global: { opt: string; consumed: boolean }[]; install: { opt: string; consumed: boolean }[] };

let home: string;
let project: string;
beforeAll(() => {
  home = mkdtempSync(join(tmpdir(), "a1125-r34-home-"));
  project = mkdtempSync(join(tmpdir(), "a1125-r34-proj-"));
  const t = new Date(Date.now() - 60_000).toISOString();
  const lines = [
    { ecosystem: "npm", package: "lodash", version: "4.17.20", verdict: "avoid", reason: "test avoid" },
    { ecosystem: "npm", package: "minimist", version: "1.2.5", verdict: "avoid", reason: "test avoid" },
    { ecosystem: "PyPI", package: "requests", version: "2.19.0", verdict: "avoid", reason: "test avoid" },
    { ecosystem: "PyPI", package: "idna", version: "2.5", verdict: "avoid", reason: "test avoid" },
    { ecosystem: "PyPI", package: "six", version: "1.16.0", verdict: "proceed" },
  ];
  writeFileSync(join(home, "check-ledger.jsonl"), lines.map((l) => JSON.stringify({ t, sv: "6.6.0", ...l })).join("\n") + "\n");
});
afterAll(() => {
  rmSync(home, { recursive: true, force: true });
  rmSync(project, { recursive: true, force: true });
});

const run = (command: string, tool = "Bash") => {
  const out = respond({ hook_event_name: "PreToolUse", cwd: project, tool_name: tool, tool_input: { command } }, { FOURDA_MCP_HOME: home }, Date.now());
  return out ? (JSON.parse(out).hookSpecificOutput?.permissionDecision ?? "other") : "none";
};
const write = (file: string, content: string) => {
  const path = join(project, file);
  const out = respond({ hook_event_name: "PreToolUse", cwd: project, tool_name: "Write", tool_input: { file_path: path, content } }, { FOURDA_MCP_HOME: home }, Date.now());
  return out ? (JSON.parse(out).hookSpecificOutput?.permissionDecisionReason ?? "") : "";
};

describe(`B1: every npm option spelling against npm ${NPM.npm}'s own parser (nopt)`, () => {
  it(`no spelling of ${NPM.spellings.length} lets an install or a fetch through`, () => {
    const wrong: string[] = [];
    for (const { opt, consumed } of NPM.spellings) {
      // npm takes the next word as the option's value: the sub-command is then install.
      if (consumed && run(`npm ${opt} ls install lodash@4.17.20`) !== "deny") wrong.push(`${opt} ls install`);
      // npm takes no value: install is the sub-command.
      if (!consumed && run(`npm ${opt} install view lodash@4.17.20`) !== "deny") wrong.push(`${opt} install view`);
    }
    expect(wrong).toEqual([]);
  });
  it.each(["npm -reg ls install lodash@4.17.20", "npm -cc ls install minimist@1.2.5", "npm --cp install config lodash@4.17.20", "npm -cc ls config set registry https://evil.example.cn/", "npm -cc ls pkg set dependencies.lodash=4.17.20", "npm -cc ls pack lodash@4.17.20", "npm --userc=evil.npmrc ci", "pnpm -Dw add lodash@4.17.20", "pnpm --save-de add lodash@4.17.20"])("%s: not read", (command) => {
    expect(run(command)).toBe("deny");
  });
  it.each(["npm ci", "npm run build", "npm -ws run build", "npm --workspaces run build", "pnpm -r run build", "npm ls"])("%s goes ahead", (command) => {
    expect(run(command)).toBe("none");
  });
});

describe(`B1: every pip option spelling against pip ${PIP.pip}'s own parser (optparse)`, () => {
  it(`no global spelling (${PIP.global.length}) or install spelling (${PIP.install.length}) lets the avoided release through`, () => {
    const wrong: string[] = [];
    for (const { opt, consumed } of PIP.global) {
      const command = consumed ? `pip ${opt} zz install requests==2.19.0` : `pip ${opt} install requests==2.19.0`;
      if (run(command) !== "deny") wrong.push(command);
    }
    for (const { opt, consumed } of PIP.install) {
      // --no-index with no --find-links installs nothing from any index (pip fails): it goes ahead (P3).
      if (opt === "--no-index") continue;
      const command = consumed ? `pip install ${opt} zz requests==2.19.0` : `pip install ${opt} requests==2.19.0`;
      if (run(command) !== "deny") wrong.push(command);
    }
    expect(wrong).toEqual([]);
  });
});

describe("B2: a requirements file is read strictly", () => {
  const SEPARATORS: [string, string][] = [["CR", "\r"], ["VT", "\v"], ["FF", "\f"], ["FS", "\x1c"], ["GS", "\x1d"], ["RS", "\x1e"], ["NEL", "\x85"], ["LS", "\u2028"], ["PS", "\u2029"]];
  for (const [label, sep] of SEPARATORS) {
    const text = `six==1.16.0${sep}idna==2.5\n`;
    it(`${label} after a requirement: the Write and each command that names the file are held`, () => {
      expect(write("requirements.txt", text)).toContain("could not be read");
      writeFileSync(join(project, "deps.txt"), text);
      for (const command of ["pip install -r deps.txt", "uv pip install -r deps.txt", "uv add -r deps.txt", "pip-sync deps.txt", "uv pip sync deps.txt", "pip download -r deps.txt"]) expect(run(command), command).toBe("deny");
      expect(run("pip install -r deps.txt", "PowerShell")).toBe("deny");
    });
  }
  it("a coding declaration other than UTF-8 is not read", () => {
    expect(write("requirements.txt", "# -*- coding: utf-7 -*-\nsix==1.16.0+AAo-idna==2.5\n")).toContain("coding declaration");
  });
  it("after the specifier only a marker, --hash or a comment", () => {
    expect(write("requirements.txt", "six==1.16.0 idna==2.5\n")).toContain("could not be read");
    expect(write("requirements.txt", 'six==1.16.0 ; python_version > "3" --hash=sha256:aa\nsix==1.16.0 --hash=sha256:aa # pinned\n')).toBe("");
  });
  it("an included file is read as strictly", () => {
    writeFileSync(join(project, "inc.txt"), "six==1.16.0\ridna==2.5\n");
    expect(write("requirements.txt", "-r inc.txt\n")).toContain("could not be read");
  });
});

describe("B3, B4: Go's flag forms and pip config --editor", () => {
  it.each(["go env --w GOPROXY=https://evil.example.cn", "go env -w=true GOSUMDB=off", "go env --w=true GONOSUMCHECK=1", "go env -w GOVCS=*:all", "go env -w GOAUTH=off", "pip config --editor notepad edit"])("%s: held", (command) => {
    expect(run(command)).toBe("deny");
  });
  it("an inert Go key goes ahead", () => {
    expect(run("go env -w GOBIN=C:/go/bin")).toBe("none");
  });
});

describe("a spec of exclusions is a range", () => {
  it("pip install django!=6.1.3 is held as a range with no verdict, not judged as latest", () => {
    expect(run('pip install "django!=6.1.3"')).toBe("deny");
  });
});

describe("B5: a verdict from an older server is on record", () => {
  it("the denial says so, instead of saying no verdict is recorded", () => {
    const old = mkdtempSync(join(tmpdir(), "a1125-r34-old-"));
    writeFileSync(join(old, "check-ledger.jsonl"), JSON.stringify({ t: new Date(Date.now() - 60_000).toISOString(), sv: "6.0.0", ecosystem: "npm", package: "lodash", version: "4.18.1", verdict: "proceed" }) + "\n");
    const out = respond({ hook_event_name: "PreToolUse", cwd: project, tool_name: "Bash", tool_input: { command: "npm i lodash@4.18.1" } }, { FOURDA_MCP_HOME: old }, Date.now());
    const text = JSON.parse(out).hookSpecificOutput.permissionDecisionReason as string;
    expect(text).toContain("from an older 4da server is on record");
    expect(text).not.toContain("No dependency_check verdict at all");
    rmSync(old, { recursive: true, force: true });
  });
});
